/**
 * A fully resolved prompt ready to be sent to an LLM.
 *
 * @param Output the type of the parsed LLM response.
 * @param ToolExecutor an object whose methods implement the template's tools,
 *   or [NoTools] if the template has no tools.
 *
 * Build and send the API request using [systemMessage], [userMessage],
 * [examples], and [tools]. If the model requests tool calls, dispatch
 * them with [executeTools] and then parse the final response with [parseResponse].
 */
data class Prompt<out Output, in ToolExecutor>(
    /** Metadata for this prompt. */
    val meta: Meta,
    val systemMessage: String,
    val userMessage: String,
    /** Few-shot examples. */
    val examples: List<FewShotExample>,
    /** The tools which can be called by the LLM, keyed by tool name. */
    val tools: Map<String, Tool>,
    val outputFormat: OutputFormat,
    val templateId: TemplateId,
    private val fromJson: (String) -> Output,
) {
    /**
     * Parse an LLM response into the expected output type.
     */
    fun parseResponse(response: String): Output {
        return doParseResponse(response, outputFormat, templateId, fromJson)
    }

    /**
     * Execute the given tool calls in parallel.
     */
    suspend fun executeTools(
        toolCalls: Iterable<ToolCall>,
        toolExecutor: ToolExecutor,
    ): List<ToolCallResponse> {
        val namespace = templateId.toString().split(':')[0]
        return coroutineScope {
            toolCalls.map { call ->
                async {
                    executeToolCall(call, namespace, toolExecutor as Any)
                }
            }.awaitAll()
        }
    }
}

